{
  "diagnosis": {
    "overallScore": 79,
    "dimensionScores": [
      {
        "dimension": "JD 硬性条件匹配",
        "score": 90,
        "comment": "审计学本科2026届应届，符合会计、审计或财务管理本科应届要求；已有会计师事务所审计实习，CPA通过会计一科为加分项，岗位未要求执业资格或签字权，硬性条件匹配度高。"
      },
      {
        "dimension": "核心职责与项目证据",
        "score": 75,
        "comment": "实习中直接涉及底稿整理、询证函准备与状态登记、存货监盘与差异整理，与审计助理核心职责高度相关；但职责以协助和基础执行为主，由项目负责人复核，缺少独立负责模块或复杂审计程序证据。"
      },
      {
        "dimension": "成果与证据强度",
        "score": 62,
        "comment": "经历可验证且边界清晰，但成果多为过程性描述，缺少底稿数量、函证数量、差异条数、核对效率等量化交付；课程项目为模拟案例，不能等同于真实客户项目成果。"
      },
      {
        "dimension": "JD 关键词与专业能力覆盖",
        "score": 85,
        "comment": "覆盖审计底稿、底稿索引、凭证附件、往来明细、询证函、发函回函状态、存货监盘、Excel、数据透视表、细节核对等关键词；CPA仅通过会计一科，关键词覆盖较好但深度有限。"
      },
      {
        "dimension": "表达质量与信息结构",
        "score": 82,
        "comment": "简历结构清晰，时间、角色、任务和复核机制表达明确，并主动声明未独立确定审计意见、无签字权，专业边界良好；可进一步按“任务—行动—交付—复核”组织并前置目标岗位关键词。"
      }
    ],
    "mainIssues": [
      "实习职责较基础，缺少独立负责或主导的审计底稿、函证跟踪、存货监盘模块，所有资料均由项目组或带教复核。",
      "成果描述偏过程性，缺少底稿份数、函证数量、回函状态比例、盘点差异条数、核对效率等可验证量化结果。",
      "课程项目为非真实客户模拟案例，商业审计项目证据有限，不能替代事务所真实项目经验。",
      "CPA仅通过会计一科，虽有加分但未形成多科通过优势，且无CPA资格和签字权。",
      "简历尚未充分按目标JD组织“细节核对”“团队任务与交付”“Excel核对数据”等关键词，重点顺序可优化。"
    ],
    "prioritySuggestions": [
      "在不编造事实的前提下，为实习经历补充具体数量或范围，如整理凭证附件或往来明细的份数、登记函证的份数、监盘差异条数及复核反馈。",
      "用“任务—个人行动—交付物—复核人”结构改写每段经历，突出本人负责部分与团队协作边界。",
      "将“审计底稿整理、底稿索引核对、函证跟踪、Excel数据核对、存货监盘差异整理”等关键词前置到个人摘要或技能栏。",
      "保留“未独立确定审计意见、无CPA资格、无签字权”等合规边界，避免夸大为主导项目或出具意见。",
      "课程项目可补充核对表、账龄数据、课程报告等交付物细节，但需标注为模拟案例，强调可迁移技能。",
      "若真实存在CPA其他科目备考或通过计划，可写“已通过会计，备考审计或税法中”，不宣称未取得资格。"
    ]
  },
  "matchItems": [
    {
      "jdRequirement": "会计、审计或财务管理本科应届毕业生",
      "resumeEvidence": "钱塘商学院审计学本科，2022.09—2026.06，2026届校招应届。",
      "evidenceStrength": "strong",
      "needsSupplement": false,
      "optimizationSuggestion": "在教育背景中直接标注“2026届审计学本科应届”，可补充与审计相关的真实主修课程，但不要虚构成绩或排名。"
    },
    {
      "jdRequirement": "能够使用Excel核对数据，工作细致",
      "resumeEvidence": "技能栏列有Excel、数据透视表；实习中整理凭证附件与往来明细并核对底稿引用和索引；课程练习中制作核对表、整理账龄数据。",
      "evidenceStrength": "medium",
      "needsSupplement": true,
      "optimizationSuggestion": "补充使用Excel核对的数据类型、规模、核对维度和差异处理方式；若真实使用VLOOKUP、数据透视表等功能可写明，不编造未用过的技能。"
    },
    {
      "jdRequirement": "协助项目组整理审计底稿",
      "resumeEvidence": "在项目经理安排下为一家制造业客户整理凭证附件与往来明细，核对底稿引用和索引，资料经项目组复核。",
      "evidenceStrength": "strong",
      "needsSupplement": true,
      "optimizationSuggestion": "按“整理凭证附件或往来明细—核对底稿引用和索引—交付项目组复核”改写，并补充底稿册数、附件份数或客户行业等真实范围。"
    },
    {
      "jdRequirement": "执行函证跟踪",
      "resumeEvidence": "协助准备询证函、登记发函与回函状态，遇到缺少资料时向带教同事反馈。",
      "evidenceStrength": "medium",
      "needsSupplement": true,
      "optimizationSuggestion": "补充函证份数、发函与回函状态登记方式、缺少资料时的反馈和跟进动作，体现跟踪闭环，但不要声称独立完成函证结论。"
    },
    {
      "jdRequirement": "参与存货监盘并核对资料",
      "resumeEvidence": "随项目组参与存货监盘，记录盘点数量与账面数量并整理差异，未独立确定审计意见。",
      "evidenceStrength": "medium",
      "needsSupplement": true,
      "optimizationSuggestion": "补充监盘地点、存货品类、盘点差异条数或差异处理方式，突出记录、核对和差异整理动作，同时保留“未独立确定审计意见”的边界。"
    },
    {
      "jdRequirement": "事务所实习经历为加分项",
      "resumeEvidence": "晟明会计师事务所审计实习生，2025.12—2026.03。",
      "evidenceStrength": "strong",
      "needsSupplement": false,
      "optimizationSuggestion": "在实习标题下补充项目组规模、客户行业和直接带教角色，突出真实事务所环境中的协作与复核流程。"
    },
    {
      "jdRequirement": "CPA考试部分科目通过为加分项",
      "resumeEvidence": "CPA考试只通过会计一科，无CPA资格，无签字权。",
      "evidenceStrength": "medium",
      "needsSupplement": true,
      "optimizationSuggestion": "如实写为“已通过CPA会计科目，无CPA资格和签字权”，若正在备考其他科目可注明备考科目，不宣称全部通过或执业资格。"
    },
    {
      "jdRequirement": "能说明本人在团队中的任务和交付",
      "resumeEvidence": "实习中由项目经理安排任务、向带教同事反馈、资料经项目组复核；课程项目担任课程组员；校园经历中配合同学完成签到。",
      "evidenceStrength": "medium",
      "needsSupplement": true,
      "optimizationSuggestion": "每段经历用“我负责、我交付、由谁复核”句式明确个人任务与交付物，区分团队成果和个人贡献，避免只写团队动作。"
    }
  ]
}
